<script>
import opportunityLayout from '@/Layouts/opportunityLayout';
export default { layout: opportunityLayout };
</script>
<script setup>
import { computed, ref } from 'vue';
import { Link, router, usePage, useForm } from '@inertiajs/vue3';
import { ArrowUpRight, Bookmark, Check, Copy, Download, Globe, Sparkles } from '@lucide/vue';
import CompanyLogo from '@/Components/Ui/CompanyLogo.vue';
import RoleCard from '@/Components/Opportunity/RoleCard.vue';
import ApplicationKitPanel from '@/Components/Opportunity/ApplicationKitPanel.vue';
import { markOpened, openedAt, isSaved, toggleSaved } from '@/composables/useOpportunityActivity';
import { appPath, isAppPath, sitePath } from '@/utils/url';
const props = defineProps({ opportunity: { type: Object, required: true }, related: { type: [Object, Array], default: () => ({ data: [] }) }, translation: { type: String, default: null }, kits: { type: Array, default: () => [] }, kitLocales: { type: Array, default: () => [] } });
const relatedListings = computed(() => Array.isArray(props.related) ? props.related : props.related?.data || []);
const page = usePage();
const fr = computed(() => page.props.locale === 'fr');
const inApp = computed(() => isAppPath(page.url));
const prefix = computed(() => inApp.value ? '/app' : fr.value ? '/fr' : '');
const publicPrefix = computed(() => fr.value ? '/fr' : '');
const text = (en, french) => fr.value ? french : en;
const dateLocale = computed(() => fr.value ? 'fr-FR' : 'en-GB');
const user = computed(() => page.props.auth?.user);
const admin = computed(() => !!user.value?.is_admin);
// Admins are candidates too, so they can apply like anyone else.
const candidate = computed(() => admin.value || user.value?.is_candidate || user.value?.userable_type === 'candidate');
const ownsIt = computed(() => props.opportunity.origin === 'native' && user.value?.userable_type === 'company' && user.value?.userable_id === props.opportunity.company?.id);
const showKit = computed(() => candidate.value && props.opportunity.is_open && !(props.opportunity.origin === 'native' && user.value?.userable_type === 'company'));
const external = computed(() => props.opportunity.application_mode === 'external');
const copied = ref(false);
const confirming = ref(false);
const notes = ref('');
const tracking = ref(false);
const reportOpen = ref(false);
const report = useForm({ reason: 'incorrect', details: '' });
const submitReport = () => report.post(route('opportunities.report', props.opportunity.id), { preserveScroll: true, onSuccess: () => { report.reset(); reportOpen.value = false; } });
const formatDay = (date) => new Intl.DateTimeFormat(dateLocale.value, { dateStyle: 'long', timeZone: 'UTC' }).format(new Date(date));
const deadline = computed(() => {
    if (props.opportunity.expires_at) return new Intl.DateTimeFormat(dateLocale.value, { dateStyle: 'long', timeZone: 'Africa/Tunis' }).format(new Date(props.opportunity.expires_at));
    if (props.opportunity.closing_date) return formatDay(props.opportunity.closing_date);
    return text('No deadline listed', 'Aucune date limite indiquée');
});
const workTypes = computed(() => fr.value ? { remote: 'À distance', hybrid: 'Hybride', onsite: 'Sur site', unknown: 'Non précisé' } : { remote: 'Remote', hybrid: 'Hybrid', onsite: 'Onsite', unknown: 'Not specified' });
const seniorityLabel = computed(() => ({ entry: text('Entry level', 'Débutant'), graduate: text('Graduate', 'Jeune diplômé'), mid: text('Mid level', 'Confirmé'), senior: 'Senior', lead: text('Lead', 'Responsable'), executive: text('Executive', 'Direction') }[props.opportunity.seniority] || props.opportunity.seniority));
const programLabel = computed(() => ({ pfe: 'PFE', summer: text('Summer internship', 'Stage d’été'), apprenticeship: text('Apprenticeship', 'Alternance'), graduate: text('Graduate programme', 'Programme jeunes diplômés'), other: text('Other programme', 'Autre programme') }[props.opportunity.program_type] || props.opportunity.program_type));
const employmentLabel = (type) => ({ FULL_TIME: text('Full time', 'Temps plein'), PART_TIME: text('Part time', 'Temps partiel'), CONTRACTOR: text('Contract / freelance', 'Contrat / freelance'), TEMPORARY: text('Temporary', 'Temporaire'), INTERN: text('Internship', 'Stage'), VOLUNTEER: text('Volunteer', 'Bénévolat'), PER_DIEM: text('Per diem', 'À la journée'), CONTRACT: text('Contract / freelance', 'Contrat / freelance'), INTERNSHIP: text('Internship', 'Stage'), OTHER: text('Other', 'Autre') }[String(type).toUpperCase().replaceAll(' ', '_').replaceAll('-', '_')] || type.replaceAll('_', ' ').toLowerCase());
const payLabel = computed(() => {
    const pay = props.opportunity.pay;
    if (!pay) return props.opportunity.compensation_status === 'unpaid' ? text('Unpaid', 'Non rémunéré') : text('Compensation not specified', 'Rémunération non précisée');
    const minimum = pay.min ?? pay.amount;
    const min = minimum == null ? null : Math.round(Number(minimum));
    const max = pay.max == null ? null : Math.round(Number(pay.max));
    const amount = min != null && max != null && min !== max ? `${min}–${max}` : min ?? max;
    const periods = fr.value ? { hour: 'heure', day: 'jour', week: 'semaine', month: 'mois', year: 'an' } : {};
    return `${amount ?? ''} ${pay.currency || text('(currency not specified)', '(devise non précisée)')}${pay.unit ? ` / ${periods[pay.unit] || pay.unit}` : ''}`;
});
const employmentLabels = computed(() => [...new Set((props.opportunity.employment_types || []).map(employmentLabel))]);
const countryName = (code) => {
    try { return new Intl.DisplayNames([page.props.locale || 'en'], { type: 'region' }).of(code) || code; } catch { return code; }
};
const countryList = (codes) => (codes || []).map(countryName).join(', ');
const whoCanApply = computed(() => {
    const role = props.opportunity;
    if (role.applicant_scope === 'anywhere') return text('Open to applicants worldwide.', 'Ouvert aux candidats du monde entier.');
    if (role.applicant_scope === 'listed') return role.eligible_countries?.length
        ? text(`Open to applicants in ${countryList(role.eligible_countries)}.`, `Ouvert aux candidats de ces pays : ${countryList(role.eligible_countries)}.`)
        : text('Only applicants in some countries can apply. The listing says which.', 'Seuls les candidats de certains pays peuvent postuler. L’offre précise lesquels.');
    if (role.applicant_scope === 'local') return role.country_code
        ? text(`You need to be allowed to work in ${countryName(role.country_code)} already.`, `Il faut déjà avoir le droit de travailler dans ce pays : ${countryName(role.country_code)}.`)
        : text('You need to be allowed to work in the job’s country already.', 'Il faut déjà avoir le droit de travailler dans le pays du poste.');
    return '';
});
const offered = (value) => ({ yes: text('Offered', 'Proposé'), no: text('Not offered', 'Non proposé') }[value]);
const hasPlaceDetails = computed(() => {
    const role = props.opportunity;
    return !!(whoCanApply.value || role.locations?.length || role.start_date || role.remote_scope || role.eligible_countries?.length || role.excluded_countries?.length || offered(role.relocation) || offered(role.visa_sponsorship));
});
const save = () => toggleSaved(props.opportunity);
const saved = computed(() => user.value ? !!props.opportunity.liked : isSaved(props.opportunity.id));
const openedLabel = computed(() => {
    const date = openedAt(props.opportunity.id);
    return date ? new Intl.DateTimeFormat(dateLocale.value, { dateStyle: 'medium', timeZone: 'Africa/Tunis' }).format(new Date(date)) : '';
});
const trackError = ref('');
const track = () => {
    tracking.value = true;
    trackError.value = '';
    router.post(route('applications.track', props.opportunity.id), { candidate_notes: notes.value }, {
        preserveScroll: true,
        onSuccess: () => { confirming.value = false; },
        onError: (errors) => { trackError.value = Object.values(errors)[0] || text('This could not be saved. Please try again.', 'Impossible d’enregistrer. Veuillez réessayer.'); },
        onFinish: () => { tracking.value = false; },
    });
};
const copyFailed = ref(false);
const copy = async () => {
    try { await navigator.clipboard.writeText(props.opportunity.public_url || window.location.href); copied.value = true; copyFailed.value = false; }
    catch { copied.value = false; copyFailed.value = true; }
};
const remove = () => {
    if (window.confirm(text('Remove this opportunity from public discovery? Existing application history will be retained.', 'Retirer cette opportunité de la recherche publique ? L’historique des candidatures sera conservé.'))) router.delete(route('opportunities.destroy', props.opportunity.id));
};
</script>
