                </section>
                <section class="bg-white border border-line rounded-2xl p-6"><h2 class="font-display text-xl font-semibold">{{ opportunity.company?.name }}</h2><p v-if="opportunity.company?.city?.name" class="text-sm text-slate-600 mt-3">{{ opportunity.company.city.name }}</p><Link v-if="opportunity.company?.public_url" :href="inApp ? appPath(opportunity.company.public_url) : sitePath(opportunity.company.public_url)" class="flex gap-2 text-sm font-semibold text-blue-700 mt-5">{{ text('See all roles at', 'Voir toutes les offres chez') }} {{ opportunity.company.name }}</Link><a v-if="opportunity.company?.website" :href="opportunity.company.website" target="_blank" rel="noopener noreferrer" class="inline-flex gap-2 text-sm font-semibold text-blue-700 mt-3">{{ text('Visit employer website', 'Visiter le site de l’employeur') }}<ArrowUpRight :size="17" /></a><p v-if="!opportunity.company?.user_id" class="mt-4 text-xs text-slate-500 leading-6">{{ text('This employer does not have a managed account on Nextward.', 'Cet employeur n’a pas de compte géré sur Nextward.') }}</p></section>
                <section class="rounded-2xl border border-line p-5"><p class="text-sm text-slate-600">{{ text('A broken link, inaccurate details, or a suspicious opportunity?', 'Un lien cassé, des informations inexactes ou une offre suspecte ?') }}</p><button type="button" class="inline-block text-sm text-blue-700 font-semibold mt-3" @click="reportOpen = !reportOpen">{{ text('Report an issue', 'Signaler un problème') }}</button><form v-if="reportOpen" class="mt-4 space-y-3" @submit.prevent="submitReport"><label class="block text-sm font-semibold">{{ text('Issue', 'Problème') }}<select v-model="report.reason" class="w-full rounded-lg border-line mt-2"><option value="closed">{{ text('Already closed', 'Déjà clôturée') }}</option><option value="broken_link">{{ text('Broken application link', 'Lien de candidature cassé') }}</option><option value="incorrect">{{ text('Incorrect information', 'Informations incorrectes') }}</option><option value="scam">{{ text('Suspicious listing', 'Offre suspecte') }}</option><option value="duplicate">{{ text('Duplicate', 'Doublon') }}</option><option value="other">{{ text('Other', 'Autre') }}</option></select></label><label class="block text-sm font-semibold">{{ text('Details (optional)', 'Détails (facultatif)') }}<textarea v-model="report.details" rows="3" maxlength="2000" class="w-full rounded-lg border-line mt-2" /></label><p v-for="(error, key) in report.errors" :key="key" class="text-xs text-red-600">{{ error }}</p><button type="submit" :disabled="report.processing" class="cta cta-primary w-full">{{ text('Send report', 'Envoyer le signalement') }}</button></form></section>
            </aside>
        </div>
        <section v-if="relatedListings.length" class="mt-14"><h2 class="font-display text-2xl font-semibold mb-6">{{ text('More opportunities to explore', 'D’autres opportunités à découvrir') }}</h2><div class="grid lg:grid-cols-2 gap-4"><RoleCard v-for="item in relatedListings" :key="item.id" :opportunity="item" /></div></section>
    </div>
</template>
